from pathlib import Path


def replace_exact(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    if old not in text:
        raise SystemExit(f"Trecho não encontrado em {path}: {old[:140]!r}")
    file.write_text(text.replace(old, new, 1))


Path("src/lib/match-minimum-player-decision.ts").write_text('''import { ApiRequestError } from './api';\nimport { withGlobalLoading } from './global-loading';\n\nexport type MinimumPlayerDecisionStatus = {\n  matchId: string;\n  confirmedPlayers: number;\n  minimumPlayers: number;\n  signupDeadline: string;\n  paymentDeadline: string | null;\n  decisionRequired: boolean;\n  belowMinimumApproved: boolean;\n};\n\nexport type ExtendSignupDeadlineInput = {\n  signupDeadlineDate: string;\n  signupDeadlineTime: string;\n  paymentDeadlineDate?: string;\n  paymentDeadlineTime?: string;\n};\n\nconst DEFAULT_API_URL = 'https://onze-organizador-de-pelada.onrender.com';\nconst REQUEST_TIMEOUT_MS = 60_000;\n\nfunction apiUrl() {\n  return (process.env.EXPO_PUBLIC_API_URL?.trim() || DEFAULT_API_URL).replace(/\\/$/, '');\n}\n\nasync function decisionRequest<T>(\n  token: string,\n  path: string,\n  options: RequestInit = {},\n  loadingMessage?: string,\n): Promise<T> {\n  return withGlobalLoading(async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);\n    try {\n      const response = await fetch(`${apiUrl()}${path}`, {\n        ...options,\n        signal: controller.signal,\n        headers: {\n          'Content-Type': 'application/json',\n          Authorization: `Bearer ${token}`,\n          ...options.headers,\n        },\n      });\n      if (!response.ok) {\n        let payload: { code?: string; message?: string } = {};\n        try {\n          payload = (await response.json()) as typeof payload;\n        } catch {\n          // Infrastructure-level responses may not contain JSON.\n        }\n        throw new ApiRequestError(\n          payload.message ?? 'Não foi possível atualizar a decisão sobre o mínimo de jogadores.',\n          response.status,\n          payload.code,\n        );\n      }\n      return (await response.json()) as T;\n    } catch (error) {\n      if (error instanceof Error && error.name === 'AbortError') {\n        throw new Error('O servidor demorou mais que o esperado para responder. Tente novamente.');\n      }\n      throw error;\n    } finally {\n      clearTimeout(timeout);\n    }\n  }, loadingMessage ? {\n    title: 'Atualizando a partida...',\n    message: loadingMessage,\n  } : {});\n}\n\nexport function getMinimumPlayerDecisionStatus(token: string, matchId: string) {\n  return decisionRequest<MinimumPlayerDecisionStatus>(\n    token,\n    `/api/matches/${matchId}/minimum-player-decision`,\n    { method: 'GET' },\n  );\n}\n\nexport function approveMatchBelowMinimum(token: string, matchId: string) {\n  return decisionRequest<MinimumPlayerDecisionStatus>(\n    token,\n    `/api/matches/${matchId}/minimum-player-decision/approve`,\n    { method: 'PUT' },\n    'Registrando que esta ocorrência continuará mesmo abaixo do mínimo.',\n  );\n}\n\nexport function extendMatchSignupDeadline(\n  token: string,\n  matchId: string,\n  input: ExtendSignupDeadlineInput,\n) {\n  return decisionRequest<MinimumPlayerDecisionStatus>(\n    token,\n    `/api/matches/${matchId}/minimum-player-decision/extend`,\n    {\n      method: 'PUT',\n      body: JSON.stringify({\n        signupDeadlineDate: input.signupDeadlineDate,\n        signupDeadlineTime: input.signupDeadlineTime,\n        paymentDeadlineDate: input.paymentDeadlineDate ?? null,\n        paymentDeadlineTime: input.paymentDeadlineTime ?? null,\n      }),\n    },\n    'Salvando os novos prazos desta ocorrência.',\n  );\n}\n''')

Path("src/components/minimum-player-decision-card.tsx").write_text('''import { useRouter } from 'expo-router';\nimport { useEffect, useState } from 'react';\nimport { Button, Text, XStack, YStack } from 'tamagui';\n\nimport { FootballMatch } from '../lib/api';\nimport { getAccessToken } from '../lib/auth-storage';\nimport {\n  approveMatchBelowMinimum,\n  getMinimumPlayerDecisionStatus,\n  MinimumPlayerDecisionStatus,\n} from '../lib/match-minimum-player-decision';\nimport { ConfirmActionModal } from './confirm-action-modal';\n\ntype Props = {\n  match: FootballMatch;\n  onCancelMatch: () => void;\n};\n\nexport function MinimumPlayerDecisionCard({ match, onCancelMatch }: Props) {\n  const router = useRouter();\n  const [status, setStatus] = useState<MinimumPlayerDecisionStatus | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [confirmKeep, setConfirmKeep] = useState(false);\n  const [saving, setSaving] = useState(false);\n\n  useEffect(() => {\n    let active = true;\n    async function load() {\n      if (!match.canManage\n          || match.status !== 'SCHEDULED'\n          || match.missingMinimumPlayers <= 0) {\n        if (active) setStatus(null);\n        return;\n      }\n      try {\n        const token = await getAccessToken();\n        if (!token) return;\n        const loaded = await getMinimumPlayerDecisionStatus(token, match.id);\n        if (active) {\n          setStatus(loaded);\n          setError(null);\n        }\n      } catch (exception) {\n        if (active) {\n          setError(exception instanceof Error\n            ? exception.message\n            : 'Não foi possível verificar a situação do número mínimo.');\n        }\n      }\n    }\n    void load();\n    return () => { active = false; };\n  }, [\n    match.id,\n    match.canManage,\n    match.status,\n    match.signupDeadline,\n    match.goingCount,\n    match.minimumPlayers,\n    match.missingMinimumPlayers,\n  ]);\n\n  async function keepBelowMinimum() {\n    if (saving) return;\n    setSaving(true);\n    setError(null);\n    try {\n      const token = await getAccessToken();\n      if (!token) return;\n      setStatus(await approveMatchBelowMinimum(token, match.id));\n      setConfirmKeep(false);\n    } catch (exception) {\n      setError(exception instanceof Error\n        ? exception.message\n        : 'Não foi possível manter a partida abaixo do mínimo.');\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  if (!match.canManage || match.status !== 'SCHEDULED' || match.missingMinimumPlayers <= 0) {\n    return null;\n  }\n\n  if (status?.belowMinimumApproved) {\n    return (\n      <YStack backgroundColor="#FFF7E6" borderColor="#D8A331" borderRadius="$6" borderWidth={1} gap="$2" padding="$5">\n        <Text color="#8A6414" fontSize={15} fontWeight="900">Partida mantida abaixo do mínimo</Text>\n        <Text color="$onzeInk" fontSize={13} lineHeight={19}>\n          O administrador decidiu manter esta ocorrência com {status.confirmedPlayers} de {status.minimumPlayers} jogadores mínimos. O formador poderá ser usado, mas posições e equilíbrio podem não ficar ideais. Revise os times antes de confirmar.\n        </Text>\n      </YStack>\n    );\n  }\n\n  if (!status?.decisionRequired) {\n    return error ? (\n      <YStack backgroundColor="#FDECEC" borderRadius="$5" padding="$4">\n        <Text color="$onzeDanger" fontSize={12}>{error}</Text>\n      </YStack>\n    ) : null;\n  }\n\n  return (\n    <>\n      <YStack backgroundColor="#FFF7E6" borderColor="#D8A331" borderRadius="$6" borderWidth={1} gap="$3" padding="$5">\n        <YStack gap="$1">\n          <Text color="#8A6414" fontSize={16} fontWeight="900">Número mínimo não atingido</Text>\n          <Text color="$onzeInk" fontSize={13} lineHeight={19}>\n            O prazo de inscrição terminou com {status.confirmedPlayers} de {status.minimumPlayers} jogadores mínimos. O que deseja fazer com esta ocorrência?\n          </Text>\n        </YStack>\n        {error ? <Text color="$onzeDanger" fontSize={12}>{error}</Text> : null}\n        <Button backgroundColor="$onzeGreen" onPress={() => router.push({\n          pathname: '/extend-match-signup',\n          params: { matchId: match.id },\n        })}>\n          <Text color="$onzeSurface" fontWeight="900">Estender prazo de inscrição</Text>\n        </Button>\n        <XStack gap="$2">\n          <Button\n            backgroundColor="$onzeCanvas"\n            borderColor="$onzeDanger"\n            borderWidth={1}\n            flex={1}\n            onPress={onCancelMatch}\n          >\n            <Text color="$onzeDanger" fontSize={12} fontWeight="900">Cancelar jogo</Text>\n          </Button>\n          <Button\n            backgroundColor="$onzeCanvas"\n            borderColor="#D8A331"\n            borderWidth={1}\n            flex={1}\n            onPress={() => setConfirmKeep(true)}\n          >\n            <Text color="#8A6414" fontSize={12} fontWeight="900" textAlign="center">Manter mesmo assim</Text>\n          </Button>\n        </XStack>\n      </YStack>\n\n      <ConfirmActionModal\n        visible={confirmKeep}\n        title="Manter abaixo do mínimo?"\n        message="O formador de times será liberado, mas com menos jogadores a distribuição de posições e o equilíbrio podem não ficar ideais. Revise a escalação antes de usar os times."\n        confirmLabel="Manter partida"\n        loading={saving}\n        onCancel={() => setConfirmKeep(false)}\n        onConfirm={() => void keepBelowMinimum()}\n      />\n    </>\n  );\n}\n''')

Path("app/extend-match-signup.tsx").write_text('''import { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useEffect, useState } from 'react';\nimport { SafeAreaView, ScrollView } from 'react-native';\nimport { Button, Input, Text, YStack } from 'tamagui';\n\nimport { ApiRequestError, FootballMatch, getMatch } from '../src/lib/api';\nimport { getAccessToken } from '../src/lib/auth-storage';\nimport { extendMatchSignupDeadline } from '../src/lib/match-minimum-player-decision';\n\nfunction parseDate(value: string) {\n  const match = value.trim().match(/^(\\d{2})\\/(\\d{2})\\/(\\d{4})$/);\n  if (!match) return null;\n  const day = Number(match[1]);\n  const month = Number(match[2]);\n  const year = Number(match[3]);\n  const date = new Date(Date.UTC(year, month - 1, day));\n  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;\n  return `${year.toString().padStart(4, '0')}-${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;\n}\n\nfunction parseTime(value: string) {\n  const match = value.trim().match(/^(\\d{1,2}):(\\d{2})$/);\n  if (!match) return null;\n  const hour = Number(match[1]);\n  const minute = Number(match[2]);\n  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;\n  return `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}:00`;\n}\n\nfunction formatDateInput(value: string) {\n  const digits = value.replace(/\\D/g, '').slice(0, 8);\n  if (digits.length <= 2) return digits;\n  if (digits.length <= 4) return `${digits.slice(0, 2)}/${digits.slice(2)}`;\n  return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4)}`;\n}\n\nfunction formatTimeInput(value: string) {\n  const digits = value.replace(/\\D/g, '').slice(0, 4);\n  if (digits.length <= 2) return digits;\n  return `${digits.slice(0, 2)}:${digits.slice(2)}`;\n}\n\nfunction formatDeadline(value: string, timeZone: string) {\n  return new Intl.DateTimeFormat('pt-BR', {\n    timeZone,\n    day: '2-digit',\n    month: '2-digit',\n    year: 'numeric',\n    hour: '2-digit',\n    minute: '2-digit',\n    hour12: false,\n  }).format(new Date(value));\n}\n\nfunction inputParts(value: string | null, timeZone: string) {\n  if (!value) return { date: '', time: '' };\n  const parts = new Intl.DateTimeFormat('pt-BR', {\n    timeZone,\n    day: '2-digit',\n    month: '2-digit',\n    year: 'numeric',\n    hour: '2-digit',\n    minute: '2-digit',\n    hour12: false,\n  }).formatToParts(new Date(value));\n  const part = (type: Intl.DateTimeFormatPartTypes) => parts.find((item) => item.type === type)?.value ?? '';\n  return {\n    date: `${part('day')}/${part('month')}/${part('year')}`,\n    time: `${part('hour')}:${part('minute')}`,\n  };\n}\n\nexport default function ExtendMatchSignupScreen() {\n  const router = useRouter();\n  const params = useLocalSearchParams<{ matchId?: string }>();\n  const [match, setMatch] = useState<FootballMatch | null>(null);\n  const [signupDate, setSignupDate] = useState('');\n  const [signupTime, setSignupTime] = useState('');\n  const [paymentDate, setPaymentDate] = useState('');\n  const [paymentTime, setPaymentTime] = useState('');\n  const [loading, setLoading] = useState(true);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    async function load() {\n      if (!params.matchId) {\n        setError('Não foi possível identificar a partida.');\n        setLoading(false);\n        return;\n      }\n      try {\n        const token = await getAccessToken();\n        if (!token) { router.replace('/'); return; }\n        const loaded = await getMatch(token, params.matchId);\n        setMatch(loaded);\n        const payment = inputParts(loaded.paymentDeadline, loaded.timeZone);\n        setPaymentDate(payment.date);\n        setPaymentTime(payment.time);\n      } catch (exception) {\n        setError(exception instanceof Error ? exception.message : 'Não foi possível carregar a partida.');\n      } finally {\n        setLoading(false);\n      }\n    }\n    void load();\n  }, [params.matchId, router]);\n\n  async function submit() {\n    if (!match || !params.matchId || saving) return;\n    setError(null);\n    const parsedSignupDate = parseDate(signupDate);\n    const parsedSignupTime = parseTime(signupTime);\n    if (!parsedSignupDate || !parsedSignupTime) {\n      setError('Informe a nova data e hora do prazo de inscrição.');\n      return;\n    }\n    const parsedPaymentDate = match.paymentRequired ? parseDate(paymentDate) : null;\n    const parsedPaymentTime = match.paymentRequired ? parseTime(paymentTime) : null;\n    if (match.paymentRequired && (!parsedPaymentDate || !parsedPaymentTime)) {\n      setError('Revise também a data e hora limite do pagamento.');\n      return;\n    }\n\n    setSaving(true);\n    try {\n      const token = await getAccessToken();\n      if (!token) { router.replace('/'); return; }\n      await extendMatchSignupDeadline(token, match.id, {\n        signupDeadlineDate: parsedSignupDate,\n        signupDeadlineTime: parsedSignupTime,\n        ...(parsedPaymentDate && parsedPaymentTime ? {\n          paymentDeadlineDate: parsedPaymentDate,\n          paymentDeadlineTime: parsedPaymentTime,\n        } : {}),\n      });\n      router.back();\n    } catch (exception) {\n      if (exception instanceof ApiRequestError && exception.code === 'PAYMENT_DEADLINE_REVIEW_REQUIRED') {\n        setError('O novo prazo de inscrição ultrapassa o prazo de pagamento. Revise também o prazo de pagamento abaixo.');\n      } else {\n        setError(exception instanceof Error ? exception.message : 'Não foi possível estender o prazo.');\n      }\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  return (\n    <SafeAreaView style={{ flex: 1, backgroundColor: '#F4F7F5' }}>\n      <ScrollView contentContainerStyle={{ padding: 20, paddingBottom: 48 }}>\n        <YStack gap="$5" paddingVertical="$3">\n          <Button alignSelf="flex-start" backgroundColor="transparent" onPress={() => router.back()}>\n            <Text color="$onzeGreen" fontWeight="800">← Voltar</Text>\n          </Button>\n          <YStack gap="$1">\n            <Text color="$onzeGreen" fontSize={13} fontWeight="900">PRAZO DE INSCRIÇÃO</Text>\n            <Text color="$onzeInk" fontSize={28} fontWeight="900">Estender prazo</Text>\n            <Text color="$onzeMuted" fontSize={13} lineHeight={19}>\n              Escolha até quando os jogadores poderão entrar na lista desta ocorrência.\n            </Text>\n          </YStack>\n\n          {error ? (\n            <YStack backgroundColor="#FDECEC" borderRadius="$5" padding="$4">\n              <Text color="$onzeDanger" fontSize={13}>{error}</Text>\n            </YStack>\n          ) : null}\n\n          {loading ? <Text color="$onzeMuted">Carregando...</Text> : null}\n\n          {match ? (\n            <>\n              <YStack backgroundColor="$onzeSurface" borderColor="$onzeBorder" borderRadius="$6" borderWidth={1} gap="$3" padding="$5">\n                <Text color="$onzeMuted" fontSize={11} fontWeight="900">PRAZO ANTERIOR</Text>\n                <Text color="$onzeInk" fontSize={14} fontWeight="800">\n                  {formatDeadline(match.signupDeadline, match.timeZone)}\n                </Text>\n                <Text color="$onzeMuted" fontSize={12}>A alteração vale somente para esta ocorrência.</Text>\n              </YStack>\n\n              <YStack backgroundColor="$onzeSurface" borderColor="$onzeBorder" borderRadius="$6" borderWidth={1} gap="$3" padding="$5">\n                <Text color="$onzeInk" fontSize={17} fontWeight="900">Novo prazo de inscrição</Text>\n                <Input\n                  keyboardType="number-pad"\n                  placeholder="DD/MM/AAAA"\n                  value={signupDate}\n                  onChangeText={(value) => setSignupDate(formatDateInput(value))}\n                />\n                <Input\n                  keyboardType="number-pad"\n                  placeholder="HH:MM"\n                  value={signupTime}\n                  onChangeText={(value) => setSignupTime(formatTimeInput(value))}\n                />\n              </YStack>\n\n              {match.paymentRequired ? (\n                <YStack backgroundColor="#FFF7E6" borderColor="#D8A331" borderRadius="$6" borderWidth={1} gap="$3" padding="$5">\n                  <Text color="#8A6414" fontSize={16} fontWeight="900">Revise o pagamento</Text>\n                  <Text color="$onzeInk" fontSize={12} lineHeight={18}>\n                    Como esta partida possui cobrança, o prazo de pagamento não pode ficar antes do novo prazo de inscrição. Confirme ou ajuste os campos abaixo.\n                  </Text>\n                  <Input\n                    keyboardType="number-pad"\n                    placeholder="DD/MM/AAAA"\n                    value={paymentDate}\n                    onChangeText={(value) => setPaymentDate(formatDateInput(value))}\n                  />\n                  <Input\n                    keyboardType="number-pad"\n                    placeholder="HH:MM"\n                    value={paymentTime}\n                    onChangeText={(value) => setPaymentTime(formatTimeInput(value))}\n                  />\n                </YStack>\n              ) : null}\n\n              <Button backgroundColor="$onzeGreen" disabled={saving} height={52} onPress={() => void submit()}>\n                <Text color="$onzeSurface" fontWeight="900">\n                  {saving ? 'Salvando...' : 'Confirmar novo prazo'}\n                </Text>\n              </Button>\n            </>\n          ) : null}\n        </YStack>\n      </ScrollView>\n    </SafeAreaView>\n  );\n}\n''')

